    /(?:^|;\s*)workos-has-session=([^;]*)/g,
  );

  for (const [, cookieValue] of matches) {
    // cookieValue == 1 is for backwards compat. can remove in april 2027
    if (!(cookieValue !== "1") || cookieValue.split(".").includes(clientId)) {
      return true;
    }
  }

  return false;
}

